import{z as n,x as l,o,c as t,q as i,j as r,D as a,d as E,s as c,S as s}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"POSIX AIO","description":"","frontmatter":{"title":"POSIX AIO","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/posix-aio.md","filePath":"cs/posix-aio.md","lastUpdated":1791063341000}'),A={name:"cs/posix-aio.md"};function p(_,e,I,B,O,u){const d=l("Mermaid");return o(),t("div",null,[e[2]||(e[2]=i('<h1 id="posix-aio" tabindex="-1">POSIX AIO <a class="header-anchor" href="#posix-aio" aria-label="Permalink to &quot;POSIX AIO&quot;">​</a></h1><div class="epigraph"><p>POSIX AIO 用 aiocb 提交读写作，完成再用信号、回调或 aio_error 轮询；Linux 上它长期不是内核真正的异步块路径。</p><footer>—— 据 POSIX aio；Linux aio(7) 对 glibc 线程池实现的警告；内核 KAIO 与 io_uring 的对照</footer></div><p><a href="/cs/direct-io">上一课</a>仍是调用线程阻塞在 <code>read</code> 上（只是不走页缓存）。高并发想「提交后去做别的」。缺口是 <strong>POSIX AIO</strong> 这套接口，以及它在 Linux 上名实不完全相符——为后课 <code>io_uring</code>/轮询 I/O 留位置，本课先钉 POSIX 名字。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>aio_read</code> 把 aiocb（fd、偏移、缓冲、字节数）排队，立即返回。完成：<code>SIGEV_SIGNAL</code>、<code>SIGEV_THREAD</code> 或 <code>aio_suspend</code>。<span class="marginnote">aiocb 直译是「异步 I/O 控制块」，可以当成一张工单：写清了要动哪个文件（fd）、从哪里开始（偏移）、搬到哪个缓冲区、搬多少字节。提交之后这张工单由系统保存，程序不必守着它——完成状态、返回字节数也都挂在工单上而不是函数返回值上。</span>缺口：glibc 常用用户态线程池阻塞在 <code>pread</code> 上，于是「异步」是线程，不是中断完成。Linux 另有 <code>io_submit</code>（KAIO），主要对 <code>O_DIRECT</code> 文件真正不阻塞。课序要求分清三套：POSIX API、KAIO、io_uring。本课对象是 POSIX 语义与陷阱。</p><p><span class="marginnote">缓冲 I/O 的 KAIO 常同步回退。信号完成与多线程难写对。教学上把它当可移植接口，性能数字另测。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>程序填 aiocb，调 <code>aio_write</code>。实现或投递内核或派工人线程。与 <a href="/cs/readahead">预读</a>：异步接口不自动等于预读窗口。与 <a href="/cs/fsync">fsync</a>：<code>aio_fsync</code> 存在，完成才表示那次同步请求结束。对照 <code>select</code> 非阻塞 fd：那是「现在能读多少」，不是「盘 I/O 完成」。</p>',8)),(o(),r(s,null,{default:a(()=>[c(d,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUB%5B%22aio_read%22%5D%20--%3E%20Q%5B%22%E9%98%9F%E5%88%97%22%5D%0A%20%20Q%20--%3E%20IMP%5B%22%E7%BA%BF%E7%A8%8B%E6%B1%A0%E6%88%96%20KAIO%22%5D%0A%20%20IMP%20--%3E%20DONE%5B%22aio_error%20%E5%AE%8C%E6%88%90%22%5D%0A%20%20DONE%20--%3E%20APP%5B%22%E4%BF%A1%E5%8F%B7%E5%A4%84%E7%90%86%E6%88%96%20suspend%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=i('<p><span class="marginnote">常见误区：初学者看到 <code>aio_read</code> 返回成功就以为数据已经在缓冲区里。实际上返回值只说明「工单收下了」。数据是否到位要另问 <code>aio_error</code>：还在 <code>EINPROGRESS</code> 就是没完，变成 \\(0\\) 才算完，出事则给出具体错误码。拿一个没完成的缓冲区去读，读到的是旧内容。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>POSIX AIO 把完成从调用栈上解开，使单线程事件循环能在理论上重叠 I/O。Linux 上若掉进线程池，重叠变成「多阻塞线程」，与用户预期的零拷贝异步不同。这解释了为何数据库与 nginx 一类后来走向 <code>io_uring</code> 或自管线程。不要把本课写成网络 aio。</p><p>错误：每个 aiocb 自己的 <code>aio_return</code>，不能当普通 errno 用完就走。</p><p>完成通知的三条路，程序侧的形态各不相同：</p>',5)),(o(),r(s,null,{default:a(()=>[c(d,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22I%2FO%20%E5%AE%8C%E6%88%90%E5%90%8E%E5%A6%82%E4%BD%95%E5%8F%AB%E9%86%92%E7%A8%8B%E5%BA%8F%3F%22%5D%20--%3E%20B%5B%22SIGEV_SIGNAL%22%5D%0A%20%20A%20--%3E%20C%5B%22SIGEV_THREAD%22%5D%0A%20%20A%20--%3E%20D%5B%22%E6%89%8B%E5%8A%A8%E8%BD%AE%E8%AF%A2%22%5D%0A%20%20B%20--%3E%20E%5B%22%E5%86%85%E6%A0%B8%E6%8A%95%E9%80%92%E5%AE%9E%E6%97%B6%E4%BF%A1%E5%8F%B7%EF%BC%8C%E5%A4%84%E7%90%86%E5%87%BD%E6%95%B0%E9%87%8C%E6%94%B6%E5%B0%BE%22%5D%0A%20%20C%20--%3E%20F%5B%22%E5%AE%9E%E7%8E%B0%E5%8F%A6%E8%B5%B7%E7%BA%BF%E7%A8%8B%E8%B7%91%E4%BD%A0%E7%9A%84%E5%9B%9E%E8%B0%83%E5%87%BD%E6%95%B0%22%5D%0A%20%20D%20--%3E%20G%5B%22aio_error%20%E9%80%90%E4%B8%AA%E9%97%AE%EF%BC%8C%E6%88%96%20aio_suspend%20%E9%9B%86%E4%B8%AD%E7%AD%89%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[E(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=i('<p><span class="marginnote">直觉类比：同步 <code>read</code> 像在快餐窗口点完餐站着等；AIO 是拿了号牌去座位做事。至于怎么知道餐好了——信号是广播叫号，线程回调是店员直接把餐送到你桌上，轮询则是自己每隔一会儿去看一眼屏幕。三条路对应 <code>SIGEV_SIGNAL</code>、<code>SIGEV_THREAD</code> 与 <code>aio_error</code>/<code>aio_suspend</code>。</span></p><p>实现上：glibc AIO 用线程池时，每个 aiocb 可能占一条阻塞线程，连接数一大就打满。KAIO 对缓冲文件常同步完成，看起来像 AIO 却没有重叠。io_uring 是后路，本课只分清名字。 读法上只引用<a href="/cs/direct-io">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「文件系统实现 / 接口进阶」课序里，对象是 <strong>POSIX AIO</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 io_uring 的 SQE 格式写完——<a href="/cs/io-polling">轮询 I/O</a> 与网络课会再遇真正的异步块层。不保证实时信号队列够用。下一课在「还要经过内核缓冲」时减少拷贝：sendfile 与 splice。</p><p>版本字段会变，课序钉的是机制对象「POSIX AIO」，不是某一主线内核的结构体名。 后课默认：POSIX AIO 是完成分离接口，Linux 实现可能是线程。把页在 fd 之间搬而不进用户空间，下一课 sendfile/splice。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>POSIX AIO 用 aiocb 异步读写；Linux glibc 常线程化。</li><li>真正的内核异步多要求 DIRECT 或后来的 uring。</li><li>sendfile/splice 是下一课。</li><li>出处：POSIX aio；Linux <code>aio(7)</code>；Love, <em>LSP</em>。</li></ul>',9))])}const f=n(A,[["render",p]]);export{P as __pageData,f as default};
